def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c

    if n == 99:
        return 'D'

    exploit_count = 0
    retaliate_count = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i+1] == 'C':
                exploit_count += 1
            else:
                retaliate_count += 1

    if n == 98:
        if exploit_count >= 2 and opp_d * 4 < n:
            return 'D'
        if opp_d == 0 and my_d > 0 and exploit_count > 0:
            return 'D'

    if n == 1:
        if op[0] == 'D':
            return 'D'
        return 'C'

    opp_rate = opp_c / n

    if opp_rate < 0.2:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if opp_rate > 0.8:
        if exploit_count >= 2:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        if exploit_count == 1:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        if my_d == 0 and opp_d == 0:
            if n == 20:
                return 'D'
            return 'C'

        recent_len = min(8, n)
        recent_op = op[-recent_len:]
        recent_me = me[-recent_len:]
        recent_opp_c = sum(1 for x in recent_op if x == 'C')
        recent_my_c = sum(1 for x in recent_me if x == 'C')

        if recent_len >= 4 and recent_opp_c == recent_len and recent_my_c >= recent_len - 1:
            return 'C'
        if recent_opp_c >= recent_len - 1:
            return 'C'
        return 'D' if rng.random() < 0.6 else 'C'

    recent_len = min(8, n)
    recent_op = op[-recent_len:]
    recent_me = me[-recent_len:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_my_c = sum(1 for x in recent_me if x == 'C')

    last_op = op[-1]
    last_me = me[-1]

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    if run_d >= 3:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    if run_c >= 4:
        if n > 50 and rng.random() < 0.1:
            return 'D'
        return 'C'

    if last_op == 'D':
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        if rng.random() < 0.06 and n < 90:
            return 'D'
        return 'C'
